import * as db from './storage.mjs';
import {registerOfflineWorker} from './pwa.mjs';
import {mountInterviews,seedInterviewPermits} from './interview-ui.mjs';
import {mapMarkup,mountMap} from './map.mjs';
import {templateFields,suggestSampleCode,dailyRecap,recapMarkup,labelForField,questionnaireEntries} from './fieldwork.mjs';
import {createWordReport} from './word-report.mjs';
import {checklistMarkup,backupMarkup,photoEditorMarkup,mountPhotoEditor} from './terrain-tools.mjs';

import {detectPermit,daysRemaining,parsePermitCSV} from './geo.mjs';

const $=s=>document.querySelector(s), uid=()=>crypto.randomUUID(), now=()=>new Date().toISOString();

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const ICONS={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',plus:'M12 4v16 M4 12h16',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.1 M3 12h.1 M3 19h.1',mission:'M3 7h18v13H3z M8 7V4h8v3 M3 11h18',more:'M5 12h.1 M12 12h.1 M19 12h.1',gps:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',camera:'M3 7h4l2-3h6l2 3h4v13H3z M12 10a3 3 0 1 0 0 6 3 3 0 0 0 0-6',mic:'M9 5a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M6 11v2a6 6 0 0 0 12 0v-2 M12 19v3 M8 22h8',save:'M4 3h14l3 3v15H3V3z M7 3v6h10V3 M7 21v-8h10v8',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',check:'M4 12l5 5L20 6',alert:'M12 3l10 18H2z M12 9v5 M12 17h.1',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M20 4l-2 2 M6 18l-2 2',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 17h8',leaf:'M20 3C4 2 2 11 7 16c6 6 15 0 13-13z M6 19L16 8',edit:'M4 16l12-12 4 4L8 20H4z',stop:'M5 5h14v14H5z',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14z M12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};

const icon=n=>`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.file}"/></svg>`;

const categories=['Affleurement','Échantillon','Accès','Eau','Occupation du sol','Rencontre','Autre'];

const prompts={Affleurement:['Roche observée','Altération','Structure visible','Indice à documenter'],Échantillon:['Référence de prélèvement','Contexte et emplacement','Conditionnement','Autorisation vérifiée'],Accès:['État de la piste','Traversée ou pont','Point de stationnement','Durée mesurée'],Eau:['Cours d’eau','État des berges','Usage observé','Traversée'], 'Occupation du sol':['Culture','Habitation','Activité observée','Contrainte à vérifier'],Rencontre:['Interlocuteur','Fonction déclarée','Information à confirmer','Contact de suivi'],Autre:['Description','Photo de contexte','Point à vérifier']};

const state={permits:[],observations:[],missions:[],assets:[],settings:[],draft:null,screen:'home',selected:null,missionId:null,filters:{query:'',permit:'',category:'',incomplete:false},selectedIds:new Set(),mapPermit:'',zoom:1,mapCenter:null,recording:false,saveState:'',storage:null,readyOffline:false};

let voiceQueue=Promise.resolve(),saveBusy=false,mapController=null,renderVersion=0;
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
state.recapDay=localDay();

let writeQueue=Promise.resolve(),recorder=null,stream=null,recordChunks=[],recordPromise=null,installPrompt=null,swReg=null,wakeLock=null,toastTimer,assetUrls=new Map(),draftSaving=false;

const setting=id=>state.settings.find(s=>s.id===id)?.value;

const date=s=>s?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(s+'T12:00:00')):'Non renseignée';

const dateTime=s=>s?new Date(s).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):'—';

const permit=id=>state.permits.find(p=>p.id===id), mission=id=>state.missions.find(m=>m.id===id);

const completion=o=>[o.title,o.category,(o.notes||o.questionnaire?.observed),o.lat!=null&&o.lng!=null,o.permitId,o.assetIds?.length].filter(Boolean).length;

const incomplete=o=>o.questionnaire?.needsReview===true||completion(o)<6;

const missionObs=()=>state.observations.filter(o=>!state.missionId||o.missionId===state.missionId);

function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}

function fail(e){console.error(e);notify(e?.message||'L’opération a échoué. Vos données déjà enregistrées sont conservées.');}

async function refresh(){[state.observations,state.missions,state.assets,state.settings]=await Promise.all(['observations','missions','assets','settings'].map(db.readAll));state.permits=setting('permits')||state.permits;[state.drafts,state.interviews,state.interviewPeople,state.interviewMeetings]=await Promise.all([db.readAll('drafts'),db.readInterviews(),db.readAll('interviewPeople'),db.readAll('interviewMeetings')]);state.storage={...await db.estimateStorage(),persisted:await navigator.storage?.persisted?.()||false};}

function recoveredDraft(id){const e=db.readEmergencyDraft(id)?.data;return e&&e.id===id&&typeof e.updatedAt==='string'&&Array.isArray(e.assetIds)?e:null;}

function emergencyDrafts(){try{return Object.keys(localStorage).filter(k=>k.startsWith('tety:emergency-draft:')).map(k=>recoveredDraft(k.slice('tety:emergency-draft:'.length))).filter(Boolean);}catch{return [];}}

async function setSetting(id,value){const record={id,value,updatedAt:now()};await db.put('settings',record);state.settings=state.settings.filter(s=>s.id!==id).concat(record);}

function navigate(screen,extra=''){location.hash=screen+extra;}

async function route(){const previous=state.screen;const [screen,query]=location.hash.slice(1).split('?');state.screen=screen||'home';const q=new URLSearchParams(query||'');state.selected=q.get('id');if(previous==='interviews'){await mapController?.flush?.().catch(fail);await refresh();}if(state.screen==='point')openDraft(state.selected).then(render).catch(fail);else render();window.scrollTo(0,0);}

async function openDraft(id){

 if(state.draft&&(!id||state.draft.id===id))return;

 let stored=id?await db.get('drafts',id):null;

 if(!id){const all=await db.readAll('drafts');stored=all.sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')))[0]||null;}

 const observed=id?state.observations.find(o=>o.id===id):null;

 const draft=stored||observed||{id:uid(),missionId:state.missionId||state.missions[0]?.id||null,permitId:null,permitConfirmed:false,title:'',category:'',notes:'',lat:null,lng:null,accuracy:null,questionnaire:{needsReview:true},assetIds:[],createdAt:now(),updatedAt:now(),status:'incomplete'};

 const emergency=recoveredDraft(draft.id);state.draft=emergency&&emergency.updatedAt>draft.updatedAt?emergency:draft;

 state.draft.questionnaire ||= {};state.draft.assetIds ||= [];await persistDraft();

}

function draftStatus(text){state.saveState=text;const el=$('#draft-status');if(el)el.textContent=text;}

function persistDraft(target=state.draft){

 if(!target)return Promise.resolve();target.updatedAt=now();const snapshot=structuredClone(target);db.saveEmergencyDraft(snapshot.id,snapshot);

 draftStatus('Enregistrement du brouillon…');draftSaving=true;

 writeQueue=writeQueue.catch(()=>{}).then(()=>db.put('drafts',snapshot)).then(()=>{draftStatus('Brouillon conservé sur cet appareil');draftSaving=false;}).catch(e=>{draftSaving=false;draftStatus('Échec du stockage local · exportez une sauvegarde');fail(e);throw e;});

 return writeQueue;

}

function header(){

 $('#header').innerHTML=`<a href="#home" class="brand"><img src="./icon.svg" alt=""><span><strong>tety</strong><small>Carnet de terrain</small></span></a><div class="header-actions"><span class="connection">${navigator.onLine?'Sur cet appareil':'Sans réseau'}</span><button class="icon quiet" data-action="settings" aria-label="Paramètres et sauvegardes">${icon('more')}</button></div>`;

 $('#navigation').innerHTML=[['home','home','Accueil'],['map','map','Carte'],['point','plus','Nouveau point'],['observations','list','Observations'],['missions','mission','Missions'],['interviews','mic','Entretiens']].map(([key,ico,label])=>`<a href="#${key}" class="${state.screen===key?'active ':''}${key==='point'?'new':''}" ${state.screen===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('');

}

function pageHead(title,sub,action=''){return `<div class="page-head"><div><p class="eyebrow">${esc(mission(state.missionId)?.name||'Reconnaissance AERP')}</p><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}

function urgent(){const p=state.permits.filter(p=>p.expiry&&daysRemaining(p.expiry)>=0&&daysRemaining(p.expiry)<=7).sort((a,b)=>a.expiry.localeCompare(b.expiry))[0];return p?`<div class="alert">${icon('alert')}<div><strong>AERP ${esc(p.id)} · échéance proche</strong><p>Fin de validité affichée : ${date(p.expiry)} (${daysRemaining(p.expiry)} jours). Confirmer le statut auprès du BCMM avant la descente.</p></div></div>`:'';}

function miniMap(p){const b=p.bounds;if(!b)return '';const project=(lat,lng)=>`${10+(lng-b.minLng)/(b.maxLng-b.minLng||1)*75},${72-(lat-b.minLat)/(b.maxLat-b.minLat||1)*64}`;return `<svg class="mini-map" viewBox="0 0 100 85" aria-hidden="true"><path d="${(p.contours||[]).map(c=>'M'+c.map(x=>project(x.lat,x.lng)).join('L')+'Z').join(' ')}" fill-rule="evenodd" fill="#b4cbbb" stroke="#538263" stroke-width="1"/></svg>`;}

function home(){const obs=missionObs(),drafts=state.draft?1:0;return `<div class="home-grid"><section class="hero"><div class="hero-top"><p class="eyebrow">Votre prochaine reconnaissance</p><span class="tag">ANDROID · HORS LIGNE</span></div><h1>Le terrain,<br>à portée de main.</h1><p>Un point, une photo, une observation.<br>Votre mission reste avec vous.</p><button data-action="new-point">${icon('plus')} Nouveau point ${icon('arrow')}</button><svg class="hero-art" viewBox="0 0 24 24"><path d="${ICONS.pin}" fill="none" stroke="currentColor" stroke-width="1"/></svg></section><div class="stats"><div class="stat"><strong>${obs.length.toString().padStart(2,'0')}</strong><span>observations enregistrées</span></div><div class="stat"><strong>${state.permits.length.toString().padStart(2,'0')}</strong><span>Permis disponibles localement</span></div><div class="stat"><strong>${obs.filter(o=>incomplete(o)).length.toString().padStart(2,'0')}</strong><span>points à compléter</span></div></div></div>${urgent()}<div class="notice">${icon('check')} <strong>${state.readyOffline?'Application préparée hors ligne':'Préparation hors ligne en cours'}</strong> · ${setting('lastExport')?'Dernière archive : '+dateTime(setting('lastExport')):'Exportez une première sauvegarde avant de partir.'}</div>${state.draft?`<div class="card"><div class="section-head" style="margin:0"><div><h3>Brouillon en cours</h3><p class="muted">${esc(state.draft.title||'Point à compléter')}</p></div><button data-action="resume">Reprendre ${icon('arrow')}</button></div></div>`:''}${state.drafts?.filter(d=>d.id!==state.draft?.id).length?`<details><summary>Autres brouillons (${state.drafts.filter(d=>d.id!==state.draft?.id).length})</summary>${state.drafts.filter(d=>d.id!==state.draft?.id).map(d=>`<div class="card"><strong>${esc(d.title||'Point à compléter')}</strong><p class="muted">${dateTime(d.updatedAt)}</p><button data-action="resume-draft" data-id="${esc(d.id)}">Reprendre ce brouillon</button></div>`).join('')}</details>`:''}<div class="section-head"><h2>Vos périmètres</h2><button class="small quiet" data-action="go-map">Tout voir ${icon('arrow')}</button></div><div class="permit-grid">${state.permits.map(p=>`<article class="card permit-card"><div class="card-top"><span class="permit-no">${esc(p.id)}</span><span class="tag ${daysRemaining(p.expiry)<=7?'urgent':''}">${p.expiry?daysRemaining(p.expiry)<0?'Échéance passée':daysRemaining(p.expiry)+' jours':'Date à confirmer'}</span></div>${miniMap(p)}<div class="local"><p><strong>${esc(p.district||p.districts?.join(' / ')||p.region||'Localisation à renseigner')}</strong><br><span class="muted">${esc(p.declaredCount??p.count)} carrés · ${esc(p.holder||'Titulaire à renseigner')}</span></p></div><div class="permit-footer"><span class="muted" style="font-size:11px">${p.expiry?'Validité au '+date(p.expiry):'Validité non renseignée'}</span><button class="small" data-action="permit" data-id="${esc(p.id)}">Fiche ${icon('arrow')}</button></div></article>`).join('')}</div><div class="section-head"><h2>Dernières observations</h2><button class="small quiet" data-action="go-observations">Consulter ${icon('arrow')}</button></div>${obs.length?obs.slice().sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))).slice(0,3).map(obsCard).join(''):`<div class="card empty">${icon('leaf')}<h3>Le carnet attend votre premier point</h3><p>Vous pouvez l’enregistrer même sans GPS ni photo.</p></div>`}<div class="card">${backupMarkup(state,setting('lastExport'))}</div><div class="quick-actions"><button data-action="go-recap">${icon('list')} Bilan de journée</button><button data-action="go-samples">${icon('file')} Échantillons</button><button data-action="backup">${icon('download')} Sauvegarder</button><button data-action="install">${icon('plus')} Installer Tety</button></div>`;}

function option(v,text,selected){return `<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(text)}</option>`;}

function field(name,label,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value??'')}" ${extra}></label>`;}

function suggestions(){const cat=state.draft.category;const uses=state.observations.filter(o=>o.category===cat).flatMap(o=>o.questionnaire?.tags||[]),counts=new Map();for(const tag of uses)counts.set(tag,(counts.get(tag)||0)+1);return [...new Set([...([...counts].sort((a,b)=>b[1]-a[1]).map(([k])=>k)),...(prompts[cat]||[])])].slice(0,12);}

function point(){const d=state.draft;if(!d)return '<div class="loading">Récupération du brouillon…</div>';return `${pageHead(state.observations.some(o=>o.id===d.id)?'Compléter le point':'Nouveau point','Enregistrez l’essentiel maintenant. Complétez les détails à votre rythme.')}<form id="point-form"><div class="form-grid"><div><section class="card"><div class="step"><b>01</b><h2>Position et AERP</h2></div><button type="button" class="primary" data-action="gps">${icon('gps')} Relever ma position</button><p class="muted" style="font-size:12px;margin:12px 0">${d.lat!=null&&d.lng!=null?`${d.lat.toFixed(6)}, ${d.lng.toFixed(6)}${d.accuracy!=null?' · précision ± '+Math.round(d.accuracy)+' m':''}`:'Aucune position relevée · saisie manuelle possible'}</p><details><summary>Coordonnées manuelles</summary><div class="two">${field('lat','Latitude',d.lat,'number','step="any" min="-90" max="90" inputmode="decimal"')}${field('lng','Longitude',d.lng,'number','step="any" min="-180" max="180" inputmode="decimal"')}</div></details><label class="field"><span>AERP à confirmer</span><select name="permitId">${option('','Non identifié',d.permitId)}${state.permits.map(p=>option(p.id,(p.type||'Permis')+' '+p.id,d.permitId)).join('')}</select><small>Proposition indicative à partir des CSV. Confirmez le titre sur le terrain.</small></label>${d.gpsMessage?`<p class="notice">${esc(d.gpsMessage)}</p>`:''}<label style="font-size:13px"><input type="checkbox" name="permitConfirmed" ${d.permitConfirmed?'checked':''}> AERP confirmé par l’équipe</label><label class="field" style="margin-top:18px"><span>Mission</span><select name="missionId">${option('','Sans mission',d.missionId)}${state.missions.map(m=>option(m.id,m.name,d.missionId)).join('')}</select></label></section><section class="card"><div class="step"><b>02</b><h2>Catégorie et repères</h2></div>${field('title','Titre de l’observation',d.title,'text','placeholder="Ex. Affleurement au bord de la piste" maxlength="240"')}<div class="chips">${categories.map(c=>`<button type="button" data-action="category" data-value="${esc(c)}" class="${d.category===c?'selected':''}" aria-pressed="${d.category===c}">${esc(c)}</button>`).join('')}</div>${d.category?`<p class="muted" style="font-size:12px;margin-top:18px">Suggestions de votre carnet · elles s’adaptent aux repères déjà utilisés</p><div class="chips">${suggestions().map(t=>`<button type="button" data-action="tag" data-value="${esc(t)}" class="${d.questionnaire.tags?.includes(t)?'selected':''}" aria-pressed="${!!d.questionnaire.tags?.includes(t)}">${esc(t)}</button>`).join('')}</div>`:''}</section></div><div><section class="card"><div class="step"><b>03</b><h2>Photos et notes</h2></div><div class="quick-actions"><button type="button" data-action="photo">${icon('camera')} Photo</button><button type="button" data-action="attach">${icon('file')} Importer</button><button type="button" data-action="record" class="${state.recording?'danger':''}">${icon(state.recording?'stop':'mic')} ${state.recording?'Arrêter la note':'Note vocale'}</button></div><div id="attachments" class="attachments">${assetMarkup(d.assetIds,true)}</div><label class="field" style="margin-top:18px"><span>Notes libres</span><textarea name="notes" placeholder="Ce que vous observez, ce qui reste à vérifier…">${esc(d.notes)}</textarea></label>${templateFields(d)}<details><summary>Contexte et suites à donner</summary>${field('q_village','Commune et village',d.questionnaire.village)}${field('q_followup','Suite à donner, responsable et délai',d.questionnaire.followup)}${field('q_source','Origine de l’information',d.questionnaire.source)}${field('q_authorization','Autorisation de prélèvement vérifiée',d.questionnaire.authorization)}${Object.keys(d.questionnaire).some(k=>['access','description','water','contact','sample'].includes(k))?`<details><summary>Champs du carnet précédent</summary>${['access','description','water','contact','sample'].map(k=>field('q_'+k,labelForField(k),d.questionnaire[k])).join('')}</details>`:''}</details><label class="review-check"><input type="checkbox" name="q_needsReview" ${d.questionnaire.needsReview?'checked':''}> À compléter le soir</label></section></div></div><div class="savebar"><div style="flex:1"><button type="submit" class="primary" style="width:100%">${icon('save')} Enregistrer le point</button><div id="draft-status" class="draft-status">${esc(state.saveState)}</div></div><button type="button" class="icon" data-action="new-draft" aria-label="Ouvrir un autre brouillon">${icon('plus')}</button></div></form>`;}

function assetMarkup(ids=[],editable=false,observation=state.draft){
 const notes=observation?.questionnaire?.photoNotes||{};
 const derived=new Set(Object.values(notes).map(n=>n.annotatedAssetId).filter(Boolean));
 return ids.filter(id=>!derived.has(id)).map(id=>{
  const a=state.assets.find(a=>a.id===id);if(!a)return `<div class="attachment">Pièce manquante ${esc(id)}</div>`;
  const n=notes[id]||{},annotated=state.assets.find(x=>x.id===n.annotatedAssetId),display=annotated||a;
  for(const file of [a,display])if(!assetUrls.has(file.id))assetUrls.set(file.id,URL.createObjectURL(file.blob));
  const url=assetUrls.get(a.id),preview=assetUrls.get(display.id);
  return `<div class="attachment">${a.type?.startsWith('image/')?`<img src="${preview}" alt="${esc(n.caption||a.name)}" loading="lazy">`:a.type?.startsWith('audio/')?`<audio src="${url}" controls preload="metadata"></audio>`:icon('file')}<div class="name">${esc(a.name)}</div><a href="${url}" download="${esc(a.name)}">Ouvrir l’original</a>${annotated?` · <a href="${preview}" download="${esc(annotated.name)}">Version annotée</a>`:''}${a.type?.startsWith('image/')?(editable?`<label class="field"><span>Légende</span><input name="photo_caption_${esc(id)}" value="${esc(n.caption||'')}" maxlength="1000" placeholder="Ce que montre la photo"></label><button type="button" data-action="annotate-photo" data-id="${esc(id)}">Annoter</button>`:`${n.caption?`<p class="photo-note">${esc(n.caption)}</p>`:''}`):''}${editable?`<button type="button" class="danger" data-action="detach" data-id="${esc(id)}">Retirer du point</button>`:''}</div>`;
 }).join('');
}

function filtered(){const f=state.filters;return missionObs().filter(o=>(!f.permit||o.permitId===f.permit)&&(!f.category||o.category===f.category)&&(!f.incomplete||incomplete(o))&&(!f.query||`${o.title} ${o.notes} ${o.permitId} ${o.category}`.toLowerCase().includes(f.query.toLowerCase()))).sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));}

function obsCard(o){return `<article class="card observation"><input type="checkbox" aria-label="Sélectionner ${esc(o.title||'Point sans titre')}" data-select="${esc(o.id)}" ${state.selectedIds.has(o.id)?'checked':''}><div class="obs-thumb">${icon(o.category==='Accès'?'map':o.category==='Échantillon'?'file':'pin')}</div><div class="obs-body"><button data-action="observation" data-id="${esc(o.id)}">${esc(o.title||'Point sans titre')}</button><div class="meta">${esc(o.category||'Catégorie à préciser')} · ${o.permitId?esc((permit(o.permitId)?.type||'Permis')+' '+o.permitId):'Permis à confirmer'} · ${dateTime(o.createdAt)}</div><p>${esc((o.notes||o.questionnaire?.observed)?.slice(0,110)||'Notes à compléter')}</p><div style="margin-top:10px"><span class="tag">${completion(o)}/6 repères</span> <span class="tag">${o.assetIds?.length||0} pièce(s)</span></div></div></article>`;}

function observations(){const items=filtered(),selected=state.observations.find(o=>o.id===state.selected);return `${pageHead('Observations',`${items.length} point(s) dans cette sélection. Recherchez, complétez et exportez vos relevés.`)}<div class="filters"><select id="filter-mission" aria-label="Filtrer par mission">${option('','Toutes les missions',state.missionId||'')}${state.missions.map(m=>option(m.id,m.name+(m.id.includes('~import')?' · copie restaurée':''),state.missionId)).join('')}</select><input id="search" type="search" placeholder="Rechercher dans le carnet" aria-label="Rechercher" value="${esc(state.filters.query)}"><select id="filter-permit" aria-label="Filtrer par AERP">${option('','Tous les AERP',state.filters.permit)}${state.permits.map(p=>option(p.id,p.id,state.filters.permit)).join('')}</select><select id="filter-category" aria-label="Filtrer par catégorie">${option('','Toutes les catégories',state.filters.category)}${categories.map(c=>option(c,c,state.filters.category)).join('')}</select><button data-action="filter-incomplete" aria-pressed="${state.filters.incomplete}">${state.filters.incomplete?'Tous les points':'À compléter'}</button></div><div class="quick-actions" style="margin-bottom:16px"><button class="small" data-action="csv">${icon('download')} CSV</button><button class="small" data-action="geojson">${icon('download')} GeoJSON</button><button class="small" data-action="word-report">${icon('file')} Carnet Word</button><button class="small" data-action="go-recap">Bilan de journée</button><button class="small" data-action="go-samples">Échantillons</button><button class="small" data-action="report">Bilan texte</button>${state.selectedIds.size?`<button class="small" data-action="bulk-mission">Déplacer ${state.selectedIds.size} point(s)</button>`:''}</div><div class="desktop-list"><div>${items.length?items.map(obsCard).join(''):'<div class="card empty"><h3>Aucun point dans cette sélection</h3><p>Créez votre premier point ou ajustez les filtres.</p><button data-action="new-point">Nouveau point</button></div>'}</div><div class="detail-pane">${selected?observationDetail(selected):`<div class="card hide-mobile"><p class="eyebrow">Consultation</p><h2>Un carnet prêt pour l’analyse</h2><p class="muted">Choisissez un point pour consulter sa fiche et ses photographies côte à côte.</p><div class="progress-track"><i style="width:${items.length?items.filter(o=>!incomplete(o)).length/items.length*100:0}%"></i></div><p>${items.filter(o=>!incomplete(o)).length} point(s) avec les six repères renseignés.</p><p class="muted" style="font-size:12px">Titre, catégorie, notes, coordonnées, AERP et pièce jointe. Cette mesure de complétude ne vaut pas validation scientifique.</p></div>`}</div></div>${items.length?`<details class="hide-mobile"><summary>Tableau détaillé</summary><div class="table-scroll"><table><thead><tr><th>Titre</th><th>AERP</th><th>Catégorie</th><th>Latitude</th><th>Longitude</th><th>Précision</th><th>Pièces</th><th>Repères</th></tr></thead><tbody>${items.map(o=>`<tr><td>${esc(o.title)}</td><td>${esc(o.permitId)}</td><td>${esc(o.category)}</td><td>${o.lat??'—'}</td><td>${o.lng??'—'}</td><td>${o.accuracy??'—'}</td><td>${o.assetIds?.length||0}</td><td>${completion(o)}/6</td></tr>`).join('')}</tbody></table></div></details>`:''}`;}

function observationDetail(o){return `<div class="card"><div class="section-head" style="margin:0 0 16px"><h2>${esc(o.title||'Point sans titre')}</h2><button class="small" data-action="edit" data-id="${esc(o.id)}">${icon('edit')} Modifier</button></div><p class="muted">${esc(o.category||'Catégorie à préciser')} · ${o.permitId?'AERP '+esc(o.permitId):'AERP à confirmer'}</p><p>${esc(o.notes||o.questionnaire?.observed||'Notes à compléter').replace(/\n/g,'<br>')}</p><p class="muted" style="font-size:12px">${o.lat!=null?o.lat.toFixed(6)+', '+o.lng.toFixed(6):'Coordonnées à compléter'}<br>AERP ${o.permitConfirmed?'confirmé par l’équipe':'à confirmer'} · ${dateTime(o.updatedAt)}</p><div class="attachments">${assetMarkup(o.assetIds,false,o)}</div>${questionnaireEntries(o.questionnaire||{}).filter(x=>x.key!=='tags'&&x.key!=='needsReview').map(({key:k,value:v})=>`<p style="margin-top:15px;font-size:13px"><strong>${esc(labelForField(k))}</strong><br>${esc(v)}</p>`).join('')}<div class="progress-track"><i style="width:${completion(o)/6*100}%"></i></div><p class="muted" style="font-size:12px">${completion(o)}/6 repères renseignés</p></div>`;}

function mapPage(){return mapMarkup({permits:state.permits,observations:missionObs(),missionId:state.missionId,mapPermit:state.mapPermit,position:state.position});}

function missionsPage(){return `${pageHead('Missions','Objectifs, checklist de départ et relevés de reconnaissance.',`<button class="icon primary" data-action="new-mission" aria-label="Nouvelle mission">${icon('plus')}</button>`)}${state.missions.map(m=>{const obs=state.observations.filter(o=>o.missionId===m.id);return `<article class="card"><div class="section-head" style="margin:0 0 12px"><h2>${esc(m.name)}</h2><span class="tag">${state.missionId===m.id?'ACTIVE':obs.length+' points'}</span></div><p class="muted">${esc(m.notes||'Programme et accès à renseigner')}</p>${m.objectives?`<p class="mission-goals"><strong>Objectifs</strong><br>${esc(m.objectives)}</p>`:''}<p>${m.date?date(m.date):'Date de départ à préciser'} · ${obs.filter(incomplete).length} point(s) à compléter</p><div class="quick-actions"><button data-action="use-mission" data-id="${esc(m.id)}">${icon('check')} Sélectionner</button><button data-action="edit-mission" data-id="${esc(m.id)}">${icon('edit')} Modifier</button><button data-action="word-report" data-id="${esc(m.id)}">Carnet Word</button><button data-action="mission-recap" data-id="${esc(m.id)}">Bilan de journée</button></div>${checklistMarkup(m)}</article>`;}).join('')}<div class="card"><h2>Entre Android et PC</h2><p class="muted">Transférez missions, observations, légendes, versions annotées, notes vocales, cartes préparées et parcours par archive. Les versions différentes sont conservées lors d’un conflit.</p>${backupMarkup(state,setting('lastExport'))}<div class="quick-actions"><button class="primary" data-action="backup">${icon('download')} Exporter l’archive</button><button data-action="restore">${icon('upload')} Importer une archive</button></div></div>`;}


function recapPage(){const recap=dailyRecap({observations:state.observations,assets:state.assets,missions:state.missions,missionId:state.missionId},state.recapDay);return `${pageHead('Bilan de journée','Retrouvez les relevés, les difficultés et les suites à donner.')}<div class="filters"><input id="recap-day" type="date" aria-label="Journée du bilan" value="${esc(state.recapDay)}"><select id="filter-mission" aria-label="Mission du bilan">${option('','Toutes les missions',state.missionId||'')}${state.missions.map(m=>option(m.id,m.name,state.missionId)).join('')}</select><button data-action="daily-word">${icon('file')} Exporter cette journée en Word</button></div>${recapMarkup(recap)}`;}
function samplesPage(){const items=missionObs().filter(o=>o.category==='Échantillon'||o.questionnaire?.sampleCode);return `${pageHead('Échantillons',`${items.length} prélèvement(s) documenté(s) dans cette mission. Les informations restent celles saisies par l’équipe.`)}<div class="filters"><select id="filter-mission" aria-label="Mission des échantillons">${option('','Toutes les missions',state.missionId||'')}${state.missions.map(m=>option(m.id,m.name,state.missionId)).join('')}</select><button data-action="new-sample">Nouveau relevé d’échantillon</button></div><div class="sample-list">${items.length?items.map(o=>`<article class="card"><p class="eyebrow">${o.permitId?'AERP '+esc(o.permitId):'AERP à confirmer'}</p><h2 class="sample-ref">${esc(o.questionnaire?.sampleCode||'Référence non renseignée')}</h2><p>${esc(o.questionnaire?.sampleDescription||o.questionnaire?.sample||o.notes||'Description non renseignée')}</p><p class="muted">Conditionnement : ${esc(o.questionnaire?.sampleConditioning||'Non renseigné')}<br>Analyse attendue : ${esc(o.questionnaire?.sampleAnalysis||'Non renseignée')}</p><button data-action="observation" data-id="${esc(o.id)}">Consulter la fiche</button></article>`).join(''):'<div class="card empty">Aucun prélèvement documenté dans cette mission.</div>'}</div>`;}
async function wordExport(id,day){await stopRecording();await writeQueue.catch(()=>{});const m=id?mission(id):mission(state.missionId);const obs=id?state.observations.filter(o=>o.missionId===id):filtered();const blob=await createWordReport({mission:m,permits:state.permits,observations:day?missionObs():obs,assets:state.assets,day});await deliver(blob,`Tety-carnet-${day||localDay()}.docx`);notify('Carnet Word produit avec les informations enregistrées.');}
async function newPointAt(position){await newDraft();const result=detectPermit(position.lat,position.lng,0,state.permits);Object.assign(state.draft,{lat:position.lat,lng:position.lng,accuracy:null,permitConfirmed:false,permitId:result.candidates.length===1?result.candidates[0].id:null,gpsMessage:'Position choisie sur la carte · à vérifier sur le terrain'});await persistDraft();render();}
async function annotatePhoto(id){const a=state.assets.find(x=>x.id===id),target=state.draft;if(!a||!target)throw new Error('Ouvrez le point avant d’annoter cette photo.');showDialog(photoEditorMarkup());await mountPhotoEditor($('#modal'),{blob:a.blob,notify,onSave:async blob=>{const asset={id:uid(),blob,name:a.name.replace(/\.[^.]+$/,'')+'-annotee.png',kind:'photo-annotation',type:'image/png',originalId:id,createdAt:now()};await db.put('assets',asset);state.assets.push(await db.get('assets',asset.id));target.questionnaire.photoNotes||={};const old=target.questionnaire.photoNotes[id]?.annotatedAssetId;target.questionnaire.photoNotes[id]={...(target.questionnaire.photoNotes[id]||{}),annotatedAssetId:asset.id};target.assetIds=target.assetIds.filter(x=>x!==old).concat(asset.id);await persistDraft(target);render();notify('Version annotée conservée avec l’original.');}});}

function settingsPage(){const persisted=state.storage?.persisted;return `${pageHead('Préparer le terrain','Installation, sauvegardes et préférences de votre appareil.')}<div class="card"><h2>Disponibilité hors ligne</h2><div class="settings-row"><div><strong>${state.readyOffline?'Application mise en cache':'Préparation à terminer'}</strong><p>Ouvrez Tety en ligne une première fois, puis vérifiez son ouverture en mode avion.</p></div>${icon(state.readyOffline?'check':'alert')}</div><div class="settings-row"><div><strong>Stockage ${persisted?'persistant accordé':'persistant à demander'}</strong><p>Le navigateur conserve les données localement. Une archive indépendante reste nécessaire.</p></div><button class="small" data-action="persist">Protéger</button></div><div class="settings-row"><div><strong>Installation Android</strong><p>Chrome → menu → Installer l’application ou Ajouter à l’écran d’accueil.</p></div><button class="small" data-action="install">Installer</button></div>${swReg?.waiting?'<button data-action="update">Appliquer la mise à jour</button>':''}</div><div class="card"><h2>Sauvegardes et exports</h2>${backupMarkup(state,setting('lastExport'))}<p style="font-size:12px">${state.assets.length} pièce(s) conservée(s) · ${state.storage?.usage!=null?(state.storage.usage/1024/1024).toFixed(1)+' Mio utilisés':'Volume de stockage non disponible'}</p><div class="quick-actions"><button class="primary" data-action="backup">${icon('download')} Sauvegarde complète</button><button data-action="restore">${icon('upload')} Restaurer / transférer</button></div><p class="notice">Conservez une copie hors du téléphone. Une fermeture brutale, un manque d’espace ou l’effacement des données du navigateur peuvent interrompre une écriture.</p></div><div class="card"><h2>Lecture et appareil</h2><div class="settings-row"><div><strong>Mode sombre</strong><p>Votre choix reste mémorisé sur cet appareil.</p></div><input aria-label="Mode sombre" id="theme-toggle" type="checkbox" ${document.body.classList.contains('dark')?'checked':''}></div><div class="settings-row"><div><strong>Texte agrandi</strong><p>Pour une lecture confortable à l’extérieur.</p></div><input aria-label="Texte agrandi" id="large-toggle" type="checkbox" ${document.body.classList.contains('large')?'checked':''}></div><div class="settings-row"><div><strong>Garder l’écran éveillé</strong><p>Si le navigateur l’autorise. Désactivé par défaut pour ménager la batterie.</p></div><input aria-label="Garder l’écran éveillé" id="wake-toggle" type="checkbox" ${setting('wake')?'checked':''}></div></div>${state.settings.filter(x=>x.id.startsWith('permits~')).map(x=>`<div class="card"><h2>Périmètres restaurés à comparer</h2><p>Une archive contient une autre configuration de ${x.value?.length||0} périmètres. Les deux versions sont conservées.</p><button data-action="adopt-permits" data-id="${esc(x.id)}">Utiliser cette configuration</button></div>`).join('')}<div class="card"><h2>Périmètres et suggestions</h2><button data-action="import-permit">${icon('upload')} Importer un CSV de carrés</button><p class="muted" style="font-size:12px;margin-top:12px">Colonnes attendues : x ; y ; lat ; lng. Les noms de commune et dates doivent être renseignés séparément. Les suggestions sont classées par usage local et ne constituent pas une expertise géologique.</p><details><summary>Confidentialité et limites</summary><p>Les observations et médias restent dans le stockage de ce navigateur. Les notes et photos restent locales. Les fonds en ligne contactent leurs fournisseurs ; la préparation d’une carte demande des données OpenStreetMap pour le secteur choisi. Les archives contiennent vos données en clair : conservez-les dans un emplacement approprié.</p><p>Le GPS peut fonctionner sans réseau mais sa précision et son délai varient. Caméra, microphone et géolocalisation demandent votre autorisation. Les notes vocales s’arrêtent quand l’application passe à l’arrière-plan ; les segments reçus sont conservés.</p><p>Version PWA 2.1 · architecture modulaire compatible avec un futur emballage Capacitor. Les comportements sur un téléphone Android physique restent à valider avec le guide de réception.</p></details></div>`;}

function render(){mapController?.destroy();mapController=null;const version=++renderVersion;header();for(const [id,url] of assetUrls){if(!state.assets.some(a=>a.id===id)){URL.revokeObjectURL(url);assetUrls.delete(id);}}$('#app').innerHTML=({home,map:mapPage,point,observations,missions:missionsPage,settings:settingsPage,recap:recapPage,samples:samplesPage,interviews:()=>'<div class="loading">Ouverture des entretiens…</div>'}[state.screen]||home)();if(state.screen==='map'){Promise.resolve(mountMap($('#app'),{permits:state.permits,observations:missionObs(),missionId:state.missionId,mapPermit:state.mapPermit,position:state.position,readSetting:setting,saveSetting:setSetting,readSettings:()=>state.settings,onSelectPermit:value=>{state.mapPermit=value;},onPermit:permitDialog,onObservation:id=>navigate('observations','?id='+id),onNewPoint:p=>newPointAt(p).catch(fail),onPosition:p=>{state.position=p;},notify})).then(controller=>{if(version!==renderVersion)controller?.destroy();else mapController=controller;}).catch(fail);}if(state.screen==='interviews'){Promise.resolve(mountInterviews($('#app'),{permits:state.permits,observations:state.observations,notify,deliver,isCurrent:()=>version===renderVersion,onPermitsChanged:items=>{state.permits=items;}})).then(controller=>{if(version!==renderVersion)controller?.destroy();else mapController=controller;}).catch(fail);}if(saveBusy)for(const el of document.querySelectorAll('#point-form input,#point-form textarea,#point-form select,#point-form button'))el.disabled=true;}

async function newDraft(){await stopRecording();await writeQueue.catch(()=>{});state.draft=null;await openDraft(uid());state.drafts=await db.readAll('drafts');if(state.screen==='point')render();else navigate('point');}

async function savePoint(){if(saveBusy)return;saveBusy=true;for(const el of document.querySelectorAll('#point-form input,#point-form textarea,#point-form select,#point-form button'))el.disabled=true;try{await stopRecording();await persistDraft();const d=structuredClone(state.draft);const code=d.questionnaire?.sampleCode?.trim();if(code&&state.observations.some(o=>o.id!==d.id&&o.questionnaire?.sampleCode?.trim().toUpperCase()===code.toUpperCase()))throw new Error('Ce code d’échantillon est déjà utilisé. Créez un code différent.');if((d.lat==null)!==(d.lng==null))throw new Error('Renseignez latitude et longitude ensemble, ou laissez les deux vides.');d.status=incomplete(d)?'incomplete':'complete';await db.saveObservation(d);await db.remove('drafts',d.id);db.removeEmergencyDraft(d.id);state.draft=null;await refresh();notify('Point enregistré sur cet appareil');saveBusy=false;navigate('observations','?id='+d.id);}finally{saveBusy=false;if(state.screen==='point')render();}}

async function gps(mapOnly=false){if(!mapOnly)await openDraft();const target=state.draft;if(!navigator.geolocation)throw new Error('Géolocalisation indisponible. Utilisez les coordonnées manuelles.');notify('Recherche de la position GPS…');const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:25000,maximumAge:0}));const {latitude:lat,longitude:lng,accuracy}=pos.coords;state.position={lat,lng,accuracy};if(mapOnly){if(mapController)mapController.updatePosition(state.position,true);else render();return;}const result=detectPermit(lat,lng,accuracy,state.permits);Object.assign(target,{lat,lng,accuracy,permitConfirmed:false,gpsMessage:result.message});if(result.candidates.length===1)target.permitId=result.candidates[0].id;else target.permitId=null;await persistDraft(target);if(state.draft?.id===target.id&&state.screen==='point')render();}

async function attachFiles(files,kind,target=state.draft){if(!target){await openDraft();target=state.draft;}for(const file of files){if(file.size>25*1024*1024)throw new Error('Une pièce dépasse 25 Mio. Importez une version plus petite.');const asset={id:uid(),blob:file,name:file.name||('Note vocale '+dateTime(now())+'.webm'),kind:kind|| (file.type.startsWith('image/')?'photo':file.type.startsWith('audio/')?'audio':'document'),type:file.type||'application/octet-stream',createdAt:now()};await db.put('assets',asset);state.assets.push(await db.get('assets',asset.id));target.assetIds.push(asset.id);await persistDraft(target);}if(state.screen==='point'&&state.draft?.id===target.id)render();notify('Pièces conservées localement');}

async function recoverVoice(target,interrupted=true){if(!target?.voiceJournal)return;const journal=target.voiceJournal,parts=journal.assetIds.map(id=>state.assets.find(a=>a.id===id)?.blob).filter(Boolean);if(parts.length){await attachFiles([new File(parts,journal.name,{type:journal.type||'audio/webm'})],'audio',target);if(interrupted)notify('Note vocale interrompue récupérée');}delete target.voiceJournal;await persistDraft(target);}

async function startRecording(){

 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Microphone non disponible. Vous pouvez importer un fichier audio.');

 const target=state.draft;stream=await navigator.mediaDevices.getUserMedia({audio:true});

 const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,type?{mimeType:type}:{});

 const journal={id:uid(),name:'Note-vocale-'+Date.now()+(recorder.mimeType.includes('mp4')?'.m4a':'.webm'),type:recorder.mimeType,assetIds:[],startedAt:now()};target.voiceJournal=journal;await persistDraft(target);

 recordPromise=new Promise((resolve,reject)=>{

  recorder.ondataavailable=e=>{if(!e.data.size)return;voiceQueue=voiceQueue.catch(()=>{}).then(async()=>{const asset={id:uid(),blob:e.data,name:'Segment-'+journal.assetIds.length+'.webm',type:e.data.type||journal.type,kind:'voice-segment',createdAt:now()};const stored=await db.put('assets',asset);state.assets.push(stored);journal.assetIds.push(asset.id);await persistDraft(target);}).catch(err=>{fail(err);throw err;});voiceQueue.catch(()=>{});};

  recorder.onerror=e=>{stream.getTracks().forEach(t=>t.stop());state.recording=false;reject(e.error||new Error('Enregistrement interrompu'));};

  recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());state.recording=false;recorder=null;try{await voiceQueue;await recoverVoice(target,false);resolve();}catch(e){reject(e);}if(state.screen==='point')render();};

 });recordPromise.catch(fail);recorder.start(1000);state.recording=true;if(state.screen==='point')render();notify('Note vocale en cours · segments sauvegardés chaque seconde');

}

async function stopRecording(){if(recorder&&recorder.state!=='inactive'){recorder.stop();await recordPromise;}}

async function deliver(blob,filename){const file=new File([blob],filename,{type:blob.type});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Tety — carnet de terrain'});return;}catch(e){if(e.name==='AbortError')return false;}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);return true;}

async function backup(){await mapController?.flush?.().catch(fail);await stopRecording();await writeQueue.catch(()=>{});const blob=await db.exportArchive();const delivered=await deliver(blob,'Tety-sauvegarde-'+new Date().toISOString().slice(0,10)+'.tety.json');if(delivered!==false){await setSetting('lastExport',now());notify('Archive exportée. Conservez-la hors du téléphone.');if(state.screen==='settings'||state.screen==='home')render();}}

function csvExport(){const items=filtered(),keys=['id','title','missionId','permitId','permitConfirmed','category','lat','lng','accuracy','notes','createdAt','updatedAt','status'];const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const safe=x=>typeof x==='string'&&/^[=+@\-\t\r]/.test(x)?"'"+x:x;const csv='\ufeff'+[keys.join(';'),...items.map(o=>keys.map(k=>quote(safe(o[k]))).join(';'))].join('\r\n');return deliver(new Blob([csv],{type:'text/csv;charset=utf-8'}),'Tety-observations.csv');}

function geoExport(){const all=filtered(),features=all.filter(o=>o.lat!=null&&o.lng!=null).map(o=>({type:'Feature',geometry:{type:'Point',coordinates:[o.lng,o.lat]},properties:{...o,datum:'Non confirmé'}}));notify(`${features.length} point(s) exportés · ${all.length-features.length} sans coordonnées exclus`);return deliver(new Blob([JSON.stringify({type:'FeatureCollection',features},null,2)],{type:'application/geo+json'}),'Tety-observations.geojson');}

function reportExport(){const obs=filtered();let text=`# Tety — Bilan de reconnaissance\n\nMission : ${mission(state.missionId)?.name||'Toutes les missions'}\nExporté le : ${dateTime(now())}\n${obs.length} observations ; ${obs.filter(incomplete).length} à compléter.\n\n`;for(const o of obs)text+=`## ${o.title||'Point sans titre'}\n\nAERP : ${o.permitId||'Non identifié'} ; confirmé : ${o.permitConfirmed?'oui':'non'}\nCatégorie : ${o.category||'Non renseignée'}\nPosition : ${o.lat??'Non renseignée'}, ${o.lng??'Non renseignée'} ; précision : ${o.accuracy??'Non renseignée'} m\n${o.notes||'Notes non renseignées'}\n\n${Object.entries(o.questionnaire||{}).map(([k,v])=>`${k} : ${v}`).join('\n')}\nPièces : ${(o.assetIds||[]).map(id=>state.assets.find(a=>a.id===id)?.name||id).join(', ')}\n\n`;text+='\nLes médias sont inclus dans l’archive complète, pas dans ce bilan.\n';return deliver(new Blob([text],{type:'text/markdown;charset=utf-8'}),'Tety-bilan-mission.md');}

function showDialog(html){$('#modal').innerHTML=html;$('#modal').showModal();history.pushState({tetyModal:true},'',location.href);}

function missionDialog(id){const m=mission(id)||{name:'',date:'',notes:''};showDialog(`<form id="mission-form" data-id="${esc(id||'')}"><h2>${id?'Modifier la mission':'Nouvelle mission'}</h2>${field('name','Nom',m.name,'text','required maxlength="240"')}${field('date','Date prévue',m.date,'date')}<label class="field"><span>Programme et accès à confirmer</span><textarea name="notes">${esc(m.notes)}</textarea></label><label class="field"><span>Objectifs de visite</span><textarea name="objectives" placeholder="Ce que l’équipe souhaite observer ou vérifier">${esc(m.objectives||'')}</textarea></label><div class="quick-actions"><button type="button" data-action="close-modal">Annuler</button><button class="primary" type="submit">Enregistrer</button></div></form>`);}

function permitDialog(id){const p=permit(id);showDialog(`<p class="eyebrow">${esc(p.holder||'Titulaire non renseigné')}</p><h2>Permis ${esc(p.id)}</h2><p><strong>${esc(p.region||'Région non renseignée')}</strong><br>${esc(p.district||p.districts?.join(' / ')||'District non renseigné')}</p><p>${esc(p.declaredCount??p.count)} carrés ${!p.cells?.length?'déclarés (sans géométrie)':''} · ${p.areaKm2!=null?p.areaKm2.toFixed(3)+' km² calculés':'Surface à confirmer'}<br>Contour conditionnel : ${esc(p.perimeterKm)??'Non renseigné'} km</p><p>Octroi : ${date(p.grant)}<br>Fin de validité affichée : ${date(p.expiry)}</p>${(p.communes||[]).map(c=>`<p style="font-size:13px">${esc(c.name)} · ${c.count} carrés</p>`).join('')}<a class="iv-button" href="#interviews?permit=${encodeURIComponent(p.id)}" onclick="document.querySelector('#modal').close()">Entretiens de ce permis</a><p>Statut enregistré : ${esc(p.status||'À vérifier')}</p><p class="notice">Vérifier le statut, les FA, les autorisations et les substances auprès des services compétents. Géométrie indicative lorsqu’elle est disponible.</p><div class="quick-actions"><button data-action="close-modal">Fermer</button><button class="primary" data-action="map-one" data-id="${esc(p.id)}">Voir la carte</button></div>`);}

async function importPermit(file){const text=await file.text();showDialog(`<form id="permit-form"><h2>Ajouter un périmètre</h2>${field('id','Numéro AERP','','text','required pattern="[0-9]{1,12}" inputmode="numeric"')}${field('holder','Titulaire')}${field('region','Région')}${field('district','District')}${field('expiry','Fin de validité connue','','date')}<p class="notice">La projection et l’unité x y restent inconnues sauf confirmation. L’identification GPS sera indicative.</p><div class="quick-actions"><button type="button" data-action="close-modal">Annuler</button><button class="primary" type="submit">Importer</button></div></form>`);state.pendingPermit=text;}

async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else showDialog('<h2>Installer Tety sur Android</h2><p>Ouvrez cette adresse dans Chrome, puis utilisez le menu ⋮ et choisissez <strong>Installer l’application</strong> ou <strong>Ajouter à l’écran d’accueil</strong>.</p><p>Attendez « Application préparée hors ligne », puis ouvrez Tety en mode avion pour vérifier la préparation. Exportez une sauvegarde avant de partir.</p><button data-action="close-modal">Compris</button>');}

async function applyWake(){if(wakeLock){await wakeLock.release();wakeLock=null;}if(setting('wake')&&document.visibilityState==='visible'&&navigator.wakeLock)try{wakeLock=await navigator.wakeLock.request('screen');}catch{notify('Le téléphone n’a pas accordé le maintien de l’écran.');}}

document.addEventListener('click',async e=>{if(saveBusy&&(e.target.closest('a')||e.target.closest('[data-action]'))){e.preventDefault();notify('Enregistrement en cours…');return;}const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action,id=btn.dataset.id;try{switch(a){case 'go-recap':navigate('recap');break;case 'go-samples':navigate('samples');break;case 'mission-recap':state.missionId=id;await setSetting('activeMission',id);navigate('recap');break;case 'word-report':btn.disabled=true;await wordExport(id);break;case 'word-day':case 'daily-word':btn.disabled=true;await wordExport(null,state.recapDay);break;case 'annotate-photo':await annotatePhoto(id);break;case 'sample-code':state.draft.questionnaire.sampleCode=suggestSampleCode({observations:state.observations,drafts:state.drafts||[],missionId:state.draft.missionId,date:localDay()});await persistDraft();render();break;case 'new-sample':await newDraft();state.draft.category='Échantillon';state.draft.questionnaire.template='sample';state.draft.questionnaire.sampleCode=suggestSampleCode({observations:state.observations,drafts:state.drafts||[],missionId:state.draft.missionId,date:localDay()});await persistDraft();render();break;case 'settings':navigate('settings');break;case 'adopt-permits':{const alternate=state.settings.find(x=>x.id===id);await db.put('settings',{id:'permits~saved-'+uid(),value:state.permits});await setSetting('permits',alternate.value);await refresh();render();break;}case 'new-point':if(state.draft)navigate('point');else await newDraft();break;case 'new-draft':if(saveBusy)break;await newDraft();break;case 'resume':navigate('point');break;case 'resume-draft':await stopRecording();await writeQueue;state.draft=null;navigate('point','?id='+id);break;case 'go-map':navigate('map');break;case 'go-observations':navigate('observations');break;case 'permit':permitDialog(id);break;case 'map-one':state.mapPermit=id;state.zoom=1;state.mapCenter=null;$('#modal').close();navigate('map');break;case 'category':state.draft.category=btn.dataset.value;state.draft.questionnaire.template=({'Affleurement':'geological','Accès':'access','Échantillon':'sample','Rencontre':'meeting'})[btn.dataset.value]||'general';await persistDraft();render();break;case 'tag':{const tags=state.draft.questionnaire.tags||[];state.draft.questionnaire.tags=tags.includes(btn.dataset.value)?tags.filter(t=>t!==btn.dataset.value):tags.concat(btn.dataset.value);await persistDraft();render();break;}case 'gps':btn.disabled=true;await gps();break;case 'map-gps':btn.disabled=true;await gps(true);break;case 'photo':$('#photo-input').click();break;case 'attach':$('#file-input').click();break;case 'record':state.recording?await stopRecording():await startRecording();break;case 'detach':{const annotation=state.draft.questionnaire.photoNotes?.[id]?.annotatedAssetId;state.draft.assetIds=state.draft.assetIds.filter(a=>a!==id&&a!==annotation);if(state.draft.questionnaire.photoNotes)delete state.draft.questionnaire.photoNotes[id];}await persistDraft();render();break;case 'observation':navigate('observations','?id='+id);break;case 'edit':await stopRecording();await writeQueue;state.draft=null;navigate('point','?id='+id);break;case 'filter-incomplete':state.filters.incomplete=!state.filters.incomplete;render();break;case 'zoom-in':state.zoom=Math.min(64,state.zoom*1.6);render();break;case 'zoom-out':state.zoom=Math.max(.25,state.zoom/1.6);render();break;case 'map-reset':state.mapCenter=null;state.zoom=1;render();break;case 'new-mission':missionDialog();break;case 'edit-mission':missionDialog(id);break;case 'use-mission':state.missionId=id;await setSetting('activeMission',id);render();notify('Mission sélectionnée');break;case 'backup':btn.disabled=true;await backup();break;case 'restore':$('#restore-input').click();break;case 'csv':await csvExport();break;case 'geojson':await geoExport();break;case 'report':await reportExport();break;case 'bulk-mission':showDialog(`<form id="bulk-form"><h2>Déplacer les points sélectionnés</h2><label class="field"><span>Mission</span><select name="missionId">${state.missions.map(m=>option(m.id,m.name,'')).join('')}</select></label><div class="quick-actions"><button type="button" data-action="close-modal">Annuler</button><button class="primary">Déplacer</button></div></form>`);break;case 'persist':await db.requestPersistence();await refresh();render();notify(state.storage?.persisted?'Stockage persistant accordé':'Le navigateur n’a pas accordé le stockage persistant. Conservez des archives.');break;case 'install':await install();break;case 'import-permit':$('#permit-input').click();break;case 'close-modal':$('#modal').close();if(history.state?.tetyModal)history.back();break;case 'update':await persistDraft();await stopRecording();swReg.waiting?.postMessage('ACTIVATE_UPDATE');navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});break;} }catch(err){if(a.includes('gps'))fail(new Error(err.code===1?'Accès GPS refusé. Autorisez la position dans les paramètres du navigateur ou saisissez-la manuellement.':err.code===3?'Position GPS non obtenue à temps. Réessayez à l’extérieur ou saisissez les coordonnées.':err.message));else fail(err);}finally{btn.disabled=false;}});

document.addEventListener('input',e=>{const el=e.target;if(el.closest('#point-form')&&el.name&&!saveBusy){let v=el.type==='checkbox'?el.checked:el.value;if(['lat','lng'].includes(el.name)){v=v===''?null:Number(v);if(v!=null&&(!Number.isFinite(v)||Math.abs(v)>(el.name==='lat'?90:180))){draftStatus('Coordonnée hors limites');return;}state.draft.permitConfirmed=false;state.draft.accuracy=null;}if(el.name==='permitId')state.draft.permitConfirmed=false;if(el.name.startsWith('photo_caption_')){const aid=el.name.slice(14);state.draft.questionnaire.photoNotes||={};state.draft.questionnaire.photoNotes[aid]={...(state.draft.questionnaire.photoNotes[aid]||{}),caption:String(v)};}else if(el.name.startsWith('q_'))state.draft.questionnaire[el.name.slice(2)]=v;else state.draft[el.name]=v|| (['permitId','missionId'].includes(el.name)?null:v);persistDraft().catch(()=>{});}if(el.id==='search'){state.filters.query=el.value;const start=el.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);}});

document.addEventListener('change',async e=>{const el=e.target;try{if(el.name==='q_template'){await persistDraft();render();}if(el.id==='recap-day'){state.recapDay=el.value||localDay();render();}if(el.dataset.checklist){const m=mission(el.dataset.mission);m.checklist={...(m.checklist||{}),[el.dataset.checklist]:el.checked};m.updatedAt=now();const snapshot=structuredClone(m);writeQueue=writeQueue.catch(()=>{}).then(()=>db.put('missions',snapshot));await writeQueue;const details=el.closest('details');if(details){const all=details.querySelectorAll('[data-checklist]');details.querySelector('summary').textContent=`Checklist de départ · ${[...all].filter(x=>x.checked).length}/${all.length}`;}}if(el.dataset.select){el.checked?state.selectedIds.add(el.dataset.select):state.selectedIds.delete(el.dataset.select);render();}if(el.id==='filter-mission'){state.missionId=el.value||null;await setSetting('activeMission',state.missionId);render();}if(el.id==='filter-permit'){state.filters.permit=el.value;render();}if(el.id==='filter-category'){state.filters.category=el.value;render();}if(el.id==='map-permit'){state.mapPermit=el.value;state.zoom=1;state.mapCenter=null;render();}if(el.id==='theme-toggle'){document.body.classList.toggle('dark',el.checked);await setSetting('theme',el.checked?'dark':'light');}if(el.id==='large-toggle'){document.body.classList.toggle('large',el.checked);await setSetting('large',el.checked);}if(el.id==='wake-toggle'){await setSetting('wake',el.checked);await applyWake();}if(el.id==='photo-input'||el.id==='file-input'){await attachFiles([...el.files]);el.value='';}if(el.id==='permit-input'){if(el.files[0])await importPermit(el.files[0]);el.value='';}if(el.id==='restore-input'&&el.files[0]){await stopRecording();await writeQueue.catch(()=>{});const r=await db.importArchive(el.files[0]);el.value='';await refresh();state.draft=null;state.missionId=null;await setSetting('activeMission',null);notify(`Archive importée · ${r.added??0} ajout(s), ${r.conflicts??0} conflit(s) conservé(s)`);render();}}catch(err){fail(err);}});

document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const submit=f.querySelector('[type=submit]')||f.querySelector('button.primary');if(submit)submit.disabled=true;try{if(f.classList.contains('checklist-add')){const m=mission(f.dataset.mission),label=String(new FormData(f).get('item')||'').trim();if(label){await db.put('missions',{...m,checklistExtra:[...(m.checklistExtra||[]),{id:uid(),group:'Personnel',label}],updatedAt:now()});await refresh();render();}}if(f.id==='point-form')await savePoint();if(f.id==='mission-form'){const form=new FormData(f),id=f.dataset.id||uid(),old=mission(id);await db.put('missions',{...old,id,name:String(form.get('name')).trim(),date:String(form.get('date')),notes:String(form.get('notes')),objectives:String(form.get('objectives')||''),createdAt:old?.createdAt||now(),updatedAt:now()});await refresh();$('#modal').close();render();}if(f.id==='bulk-form'){const mid=new FormData(f).get('missionId');for(const id of state.selectedIds){const o=state.observations.find(o=>o.id===id);if(o)await db.saveObservation({...o,missionId:mid,updatedAt:now()});}state.selectedIds.clear();await refresh();$('#modal').close();render();}if(f.id==='permit-form'){const form=new FormData(f),id=String(form.get('id'));if(state.permits.some(p=>p.id===id))throw new Error('Ce numéro est déjà présent. Choisissez un autre numéro pour conserver les données existantes.');const p=parsePermitCSV(state.pendingPermit,{id,holder:String(form.get('holder')),region:String(form.get('region')),district:String(form.get('district')),expiry:String(form.get('expiry'))||null});state.permits.push(p);await setSetting('permits',state.permits);state.pendingPermit=null;$('#modal').close();render();notify(p.count+' points importés localement');}}catch(err){fail(err);}finally{if(submit)submit.disabled=false;}});

window.addEventListener('popstate',()=>{if($('#modal').open)$('#modal').close();});window.addEventListener('hashchange',async()=>{await stopRecording().catch(fail);route().catch(fail);});window.addEventListener('online',header);window.addEventListener('offline',header);

window.addEventListener('pagehide',()=>{if(state.draft)db.saveEmergencyDraft(state.draft.id,state.draft);if(recorder?.state==='recording')recorder.stop();});

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){persistDraft().catch(()=>{});stopRecording().catch(fail);}else{applyWake().catch(fail);header();}});

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('appinstalled',()=>notify('Tety est installé sur cet appareil'));

async function prepareOffline(){if(!('serviceWorker'in navigator))return;const {registration,worker}=await registerOfflineWorker(new URL('./',import.meta.url));swReg=registration;state.readyOffline=await new Promise(resolve=>{const channel=new MessageChannel();const timer=setTimeout(()=>resolve(false),5000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data.ready===true);};worker.postMessage('OFFLINE_STATUS',[channel.port2]);});if(state.screen==='home'||state.screen==='settings')render();navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swReg.waiting===null&&navigator.serviceWorker.controller)notify('Application hors ligne prête');});swReg.addEventListener('updatefound',()=>{const w=swReg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)notify('Une mise à jour est disponible dans les paramètres.');});});}

async function init(){try{await db.openStore();await refresh();if(!state.permits.length){state.permits=await (await fetch('./permits.json')).json();await setSetting('permits',state.permits);}const seededPermits=seedInterviewPermits(state.permits);if(seededPermits.length!==state.permits.length){state.permits=seededPermits;await setSetting('permits',state.permits);}if(!state.missions.length){await db.put('missions',{id:'mission-manajary',name:'Reconnaissance MANAJARY',notes:'Nosy Varika en priorité · Mananjary · Vangaindrano et Vondrozo. Accès et dates à confirmer.',date:'',createdAt:now(),updatedAt:now()});await refresh();}state.missionId=setting('activeMission')===undefined?state.missions[0]?.id:setting('activeMission');const drafts=[...await db.readAll('drafts'),...emergencyDrafts()];const draft=drafts.sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')))[0];if(draft){const emergency=recoveredDraft(draft.id);state.draft=emergency&&emergency.updatedAt>draft.updatedAt?emergency:draft;}if(state.draft?.voiceJournal)await recoverVoice(state.draft);state.assets=await db.readAll('assets');document.body.classList.toggle('dark',(setting('theme')|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))==='dark');document.body.classList.toggle('large',!!setting('large'));await route();prepareOffline().catch(e=>{console.error(e);notify('Préparation hors ligne incomplète. Réouvrez Tety avec une connexion.');});}catch(e){header();$('#app').innerHTML=`<div class="error-panel"><h1>Le carnet ne peut pas s’ouvrir</h1><p>${esc(e.message)}</p><p>Vérifiez l’espace libre et l’autorisation de stockage du navigateur. Vos fichiers déjà exportés peuvent être restaurés après réouverture.</p><button onclick="location.reload()">Réessayer</button></div>`;}}

init();

